  end;
  begin
    r := r || jsonb_build_object('deadlocks_total', (select value from (select coalesce(sum(deadlocks),0) as value from pg_stat_database) q limit 1));
  exception when others then
    r := r || jsonb_build_object('deadlocks_total', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('failed_login_attempts_24h', (select value from (select coalesce(sum(fail_count),0) as value from login_attempts where window_start > now() - interval '24 hours') q limit 1));
  exception when others then
    r := r || jsonb_build_object('failed_login_attempts_24h', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('locked_out_identifiers_now', (select value from (select count(*) as value from login_attempts where locked_until > now()) q limit 1));
  exception when others then
    r := r || jsonb_build_object('locked_out_identifiers_now', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('suspicious_identifiers_locked_or_high_fail', (select coalesce(jsonb_agg(q), '[]'::jsonb) from (select identifier, ip, fail_count, window_start, locked_until from login_attempts where locked_until > now() or fail_count >= 3 order by fail_count desc, window_start desc limit 25) q));
  exception when others then
    r := r || jsonb_build_object('suspicious_identifiers_locked_or_high_fail', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('slowest_queries_by_mean_exec_time', (select coalesce(jsonb_agg(q), '[]'::jsonb) from (select left(regexp_replace(query, '\s+', ' ', 'g'), 110) as query, calls, round(mean_exec_time::numeric, 1) as mean_ms, round(total_exec_time::numeric, 0) as total_ms from extensions.pg_stat_statements where query not ilike '%pg_stat_statements%' and query not ilike '%pg_stat_activity%' and calls > 1 order by mean_exec_time desc limit 15) q));
  exception when others then
    r := r || jsonb_build_object('slowest_queries_by_mean_exec_time', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('object_storage_used', (select value from (select coalesce(sum(bytes),0) as value from v_storage_health) q limit 1));
  exception when others then
    r := r || jsonb_build_object('object_storage_used', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('storage_by_bucket', (select coalesce(jsonb_agg(q), '[]'::jsonb) from (select bucket_id, objects, bytes, newest_at from v_storage_health order by bytes desc) q));
  exception when others then
