  end;
  begin
    r := r || jsonb_build_object('db_storage_size_trend', (select coalesce(jsonb_agg(q), '[]'::jsonb) from (select captured_at as time, db_bytes as "DB size", storage_bytes as "Storage" from ops_db_size_history order by captured_at) q));
  exception when others then
    r := r || jsonb_build_object('db_storage_size_trend', jsonb_build_object('error', sqlerrm));
  end;
  return r;
end $fn$;
