-- workhive-errors: 6 panel(s), "WorkHive App Errors (GlitchTip)" - GlitchTip's own database, through the bridge
create extension if not exists dblink with schema extensions;
create or replace function public.console_read_errors(p_from timestamptz default now() - interval '30 days',
  p_to timestamptz default now(), p_hive uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public, extensions, pg_temp as $fn$
declare
  r jsonb := jsonb_build_object('dashboard', 'workhive-errors', 'from', p_from, 'to', p_to, 'read_at', now());
  conn text;
begin
  if not public.is_platform_admin() then
    raise exception 'Only platform admins can read the operator console.' using errcode = '42501';
  end if;
  select decrypted_secret into conn from vault.decrypted_secrets where name = 'glitchtip_read_url';
  if conn is null then
    return r || jsonb_build_object('connected', false, 'reason',
      'No error tracker is connected to this database, so its numbers cannot be read here.');
  end if;
  begin
    perform 1 from extensions.dblink(conn, 'select 1') as t(x int);
  exception when others then
    return r || jsonb_build_object('connected', false, 'reason', 'The error tracker did not answer: ' || sqlerrm);
  end;
  begin
    r := r || jsonb_build_object('unresolved_issues', (select t.j::jsonb from extensions.dblink(conn, $q$select to_json((select value from (select count(*) as value from issue_events_issue where status = 0 and is_deleted is not true) q limit 1))::text$q$) as t(j text)));
  exception when others then
    r := r || jsonb_build_object('unresolved_issues', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('new_issues_24h', (select t.j::jsonb from extensions.dblink(conn, $q$select to_json((select value from (select count(*) as value from issue_events_issue where first_seen > now() - interval '24 hours' and is_deleted is not true) q limit 1))::text$q$) as t(j text)));
  exception when others then
    r := r || jsonb_build_object('new_issues_24h', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('events_24h', (select t.j::jsonb from extensions.dblink(conn, $q$select to_json((select value from (select count(*) as value from issue_events_issueevent where received > now() - interval '24 hours') q limit 1))::text$q$) as t(j text)));
  exception when others then
    r := r || jsonb_build_object('events_24h', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('error_issues_active_24h', (select t.j::jsonb from extensions.dblink(conn, $q$select to_json((select value from (select count(*) as value from issue_events_issue where level >= 4 and status = 0 and last_seen > now() - interval '24 hours' and is_deleted is not true) q limit 1))::text$q$) as t(j text)));
  exception when others then
    r := r || jsonb_build_object('error_issues_active_24h', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('top_unresolved_issues_by_event_count', (select t.j::jsonb from extensions.dblink(conn, $q$select coalesce(json_agg(q), '[]'::json)::text from (select case level when 5 then 'fatal' when 4 then 'error' when 3 then 'warning' when 2 then 'info' when 1 then 'debug' else level::text end as level, count as events, left(title, 90) as issue, left(coalesce(culprit,''), 60) as culprit, last_seen from issue_events_issue where status = 0 and is_deleted is not true order by count desc, last_seen desc limit 25) q$q$) as t(j text)));
  exception when others then
    r := r || jsonb_build_object('top_unresolved_issues_by_event_count', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('error_events_over_time_7d', (select t.j::jsonb from extensions.dblink(conn, $q$select coalesce(json_agg(q), '[]'::json)::text from (select date_trunc('hour', received) as time, count(*) as events from issue_events_issueevent where received > now() - interval '7 days' group by 1 order by 1) q$q$) as t(j text)));
  exception when others then
    r := r || jsonb_build_object('error_events_over_time_7d', jsonb_build_object('error', sqlerrm));
  end;
  return r || jsonb_build_object('connected', true);
end $fn$;
