  end;
  begin
    r := r || jsonb_build_object('onboarding_completion', (select value from (select round(100.0 * count(*) filter (where (intent is not null and intent::text not in ('null','{}','[]')) or preferred_persona is not null) / nullif(count(*),0), 0) as value from hives) q limit 1));
  exception when others then
    r := r || jsonb_build_object('onboarding_completion', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('active_hives_7d', (select value from (select count(distinct h.id) as value from hives h join analytics_events e on e.hive_id = h.id and e.created_at > now() - interval '7 days') q limit 1));
  exception when others then
    r := r || jsonb_build_object('active_hives_7d', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('active_workers_24h', (select value from (select count(distinct worker_name) as value from analytics_events where worker_name is not null and created_at > now() - interval '24 hours') q limit 1));
  exception when others then
    r := r || jsonb_build_object('active_workers_24h', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('signup_funnel_hive_lifecycle', (select coalesce(jsonb_agg(q), '[]'::jsonb) from (select stage, hives from ( select 1 ord, 'Signed up' stage, (select count(*) from hives)::int hives union all select 2, 'Onboarded', (select count(*) from hives where (intent is not null and intent::text not in ('null','{}','[]')) or preferred_persona is not null)::int union all select 3, 'Activated', (select count(distinct h.id) from hives h join analytics_events e on e.hive_id=h.id)::int union all select 4, 'Active 7d', (select count(distinct h.id) from hives h join analytics_events e on e.hive_id=h.id and e.created_at>now()-interval '7 days')::int union all select 5, 'Active 24h', (select count(distinct h.id) from hives h join analytics_events e on e.hive_id=h.id and e.created_at>now()-interval '24 hours')::int ) f order by ord) q));
  exception when others then
    r := r || jsonb_build_object('signup_funnel_hive_lifecycle', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('top_product_actions_30d', (select coalesce(jsonb_agg(q), '[]'::jsonb) from (select event_name, count(*) as events from analytics_events where event_name <> 'page_view' and created_at > now() - interval '30 days' group by event_name order by events desc limit 15) q));
  exception when others then
    r := r || jsonb_build_object('top_product_actions_30d', jsonb_build_object('error', sqlerrm));
  end;
  return r;
end $fn$;
revoke all on function public.console_read_growth(timestamptz, timestamptz, uuid) from public, anon;
grant execute on function public.console_read_growth(timestamptz, timestamptz, uuid) to authenticated;

-- workhive-slo-arct: 6 panel(s), "WorkHive SLO / Golden Signals (Arc T)"
create or replace function public.console_read_slo_arct(p_from timestamptz default now() - interval '30 days',
  p_to timestamptz default now(), p_hive uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public, extensions, pg_temp as $fn$
declare r jsonb := jsonb_build_object('dashboard', 'workhive-slo-arct', 'from', p_from, 'to', p_to, 'read_at', now());
begin
  if not public.is_platform_admin() then
    raise exception 'Only platform admins can read the operator console.' using errcode = '42501';
  end if;
  begin
    r := r || jsonb_build_object('errors_range', (select value from (select count(*) as value from wh_traces where error_code is not null and coalesce(status,0) not in (401,403,429) and (created_at >= p_from and created_at < p_to)) q limit 1));
  exception when others then
    r := r || jsonb_build_object('errors_range', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('traced_total_range', (select value from (select count(*) as value from wh_traces where (created_at >= p_from and created_at < p_to)) q limit 1));
  exception when others then
    r := r || jsonb_build_object('traced_total_range', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('errors_by_route_28d', (select coalesce(jsonb_agg(q), '[]'::jsonb) from (select route, count(*) filter (where error_code is not null and coalesce(status,0) not in (401,403,429)) as errors, count(*) filter (where status in (401,403,429)) as policy_rejections, count(*) as traced from wh_traces where created_at > now() - interval '28 days' group by 1 order by 2 desc, 4 desc limit 50) q));
  exception when others then
    r := r || jsonb_build_object('errors_by_route_28d', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('errors_over_time_excl_401_403_429', (select coalesce(jsonb_agg(q), '[]'::jsonb) from (select date_trunc('hour', created_at) as time, count(*) as errors from wh_traces where error_code is not null and coalesce(status,0) not in (401,403,429) and (created_at >= p_from and created_at < p_to) group by 1 order by 1) q));
  exception when others then
    r := r || jsonb_build_object('errors_over_time_excl_401_403_429', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('latency_p95_p50_ms', (select coalesce(jsonb_agg(q), '[]'::jsonb) from (select date_trunc('hour', created_at) as time, percentile_cont(0.95) within group (order by latency_ms) as p95_ms, percentile_cont(0.5) within group (order by latency_ms) as p50_ms from wh_traces where latency_ms is not null and (created_at >= p_from and created_at < p_to) group by 1 order by 1) q));
  exception when others then
    r := r || jsonb_build_object('latency_p95_p50_ms', jsonb_build_object('error', sqlerrm));
  end;
  begin
    r := r || jsonb_build_object('errors_by_code_range', (select coalesce(jsonb_agg(q), '[]'::jsonb) from (select error_code, count(*) as count from wh_traces where error_code is not null and (created_at >= p_from and created_at < p_to) group by 1 order by 2 desc) q));
  exception when others then
    r := r || jsonb_build_object('errors_by_code_range', jsonb_build_object('error', sqlerrm));
  end;
  return r;
end $fn$;
revoke all on function public.console_read_slo_arct(timestamptz, timestamptz, uuid) from public, anon;
grant execute on function public.console_read_slo_arct(timestamptz, timestamptz, uuid) to authenticated;

